 1	/**
 2	 * Unit tests for PollingManager.
 3	 *
 4	 * All dependencies (ProjectManager, WorkspaceManager, fetchStatusFn) are
 5	 * replaced with lightweight in-memory mocks so no real git I/O or disk I/O
 6	 * is needed.
 7	 */
 8	import { test } from 'node:test';
 9	import assert from 'node:assert/strict';
10	import type { AppConfig } from '../../config/config.types.js';
11	import type { ProjectManager } from '../../models/project/project.manager.js';
12	import type { WorkspaceManager } from '../../models/workspace/workspace.manager.js';
13	import type { WorkspaceInfo } from '../../models/workspace/workspace.types.js';
14	import type { GitStatusInfo } from '../../git/git.types.js';
15	import { PollingManager } from '../pollingManager.js';
16	
17	// ---------------------------------------------------------------------------
18	// Minimal stubs / factories
19	// ---------------------------------------------------------------------------
20	
21	const BASE_CONFIG: AppConfig = {
22	    projectsFolder: '/fake/projects',
23	    storageFolder: '/fake/storage',
24	    cloneDepth: 50,
25	    serverPort: 4200,
26	    gitPollingIntervalSeconds: 30,
27	    notesCardHeight: 220,
28	    notesColumns: 2,
29	};
30	
31	function makeStatus(branch = 'main'): GitStatusInfo {
32	    return {
33	        currentBranch: branch,
34	        localCommits: 0,
35	        unfetchedCommits: 0,
36	        modifiedFiles: 0,
37	        lastActivity: '2024-01-01T00:00:00Z',
38	        hasConflicts: false,
39	    };
40	}
41	
42	interface MockProject {
43	    Id: string;
44	    Repositories: string[];
45	    Workspaces: Record<string, unknown>;
46	    [key: string]: unknown;
47	}
48	
49	function makeProjectManager(projects: MockProject[]): ProjectManager {
50	    return {
51	        list: () => projects.map((p) => ({ Id: p.Id, Name: p.Id })),
52	        getById: (id: string) => projects.find((p) => p.Id === id) ?? undefined,
53	        updateLastActivity: (_id: string, _value: string) => { /* no-op */ },
54	    } as unknown as ProjectManager;
55	}
56	
57	function makeWorkspaceManager(workspaces: Record<string, WorkspaceInfo | undefined>): WorkspaceManager {
58	    return {
59	        getById: (projectId: string, workspaceId: string): WorkspaceInfo | undefined => {
60	            return workspaces[`${projectId}:${workspaceId}`];
61	        },
62	    } as unknown as WorkspaceManager;
63	}
64	
65	/**
66	 * Returns a mock WorkspaceManager where every (projectId, workspaceId) combo
67	 * that has the form `<project>:STABLE` is treated as existing.
68	 */
69	function makeDefaultWorkspaceManager(): WorkspaceManager {
70	    return {
71	        getById: (projectId: string, workspaceId: string): WorkspaceInfo | undefined => {
72	            if (workspaceId === 'STABLE') {
73	                return {
74	                    ProjectID: projectId,
75	                    WorkspaceID: 'STABLE',
76	                    Description: '',
77	                    DateCreated: '',
78	                    DateModified: '',
79	                    Notes: '',
80	                };
81	            }
82	            return undefined;
83	        },
84	    } as unknown as WorkspaceManager;
85	}
