 70	/**
 71	 * Creates a lightweight mock of ErrorLogManager that records every `append()` call.
 72	 */
 73	function makeErrorLogManager(): { mock: ErrorLogManager; calls: Array<Omit<ErrorLogEntry, 'Id' | 'Timestamp'>> } {
 74	    const calls: Array<Omit<ErrorLogEntry, 'Id' | 'Timestamp'>> = [];
 75	    const mock = {
 76	        append(entry: Omit<ErrorLogEntry, 'Id' | 'Timestamp'>): ErrorLogEntry {
 77	            calls.push(entry);
 78	            return { ...entry, Id: calls.length, Timestamp: new Date().toISOString() };
 79	        },
 80	    } as unknown as ErrorLogManager;
 81	    return { mock, calls };
 82	}
